                    <h2 id="mini-app-surveycraft-POSTapi-miniapp-surveycraft">Store a newly created survey in storage.</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>



<span id="example-requests-POSTapi-miniapp-surveycraft">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://127.0.0.1:9001/api/miniapp/surveycraft" \
    --header "Authorization: Bearer Bearer {YOUR_AUTH_TOKEN}" \
    --header "Content-Type: multipart/form-data" \
    --header "Accept: application/json" \
    --form "survey_id=SURVEY-001"\
    --form "title=Customer Satisfaction Survey"\
    --form "questions=10"\
    --form "description=Survey to measure customer satisfaction."\
    --form "published_link=https://example.com/survey/123"\
    --form "owner_id=1"\
    --form "timestamp=2023-01-01 12:00:00"\
    --form "json_file=@C:\Users\user\AppData\Local\Temp\php8C2B.tmp" </code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://127.0.0.1:9001/api/miniapp/surveycraft"
);

const headers = {
    "Authorization": "Bearer Bearer {YOUR_AUTH_TOKEN}",
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('survey_id', 'SURVEY-001');
body.append('title', 'Customer Satisfaction Survey');
body.append('questions', '10');
body.append('description', 'Survey to measure customer satisfaction.');
body.append('published_link', 'https://example.com/survey/123');
body.append('owner_id', '1');
body.append('timestamp', '2023-01-01 12:00:00');
body.append('json_file', document.querySelector('input[name="json_file"]').files[0]);

fetch(url, {
    method: "POST",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>

